{"content": "from typing import Dict, List

from pydantic import BaseModel, TypeAdapter


class Reading(BaseModel):
    sensor: str
    value: float


_readings_adapter = TypeAdapter(List[Reading])
_thresholds_adapter = TypeAdapter(Dict[str, float])


def parse_readings(rows: list) -> List[Reading]:
    return _readings_adapter.validate_python(rows)


def parse_thresholds(raw: dict) -> Dict[str, float]:
    return _thresholds_adapter.validate_python(raw)
"}
